				hadChosen = true
			}
		}
		if !hadChosen {
			skipped++
			t.Logf("seed %d: SKIP (no replica has the proposed value)", seed)
			continue
		}

		recoverer := -1
		for i := 1; i < 5; i++ {
			if !randomFaultHasChosen(c.instance(i, 0, 0), chosen) {
				recoverer = i
				break

				putCount++
